#include <atomic>
#include <hazard_pointer>

struct Node : std::hazard_pointer_obj_base<Node> { int value = 0; };
std::atomic<Node*> head{new Node()};

int read() {
  std::hazard_pointer keep;
  Node* p;
  {
    std::hazard_pointer h = std::make_hazard_pointer();
    p = h.protect(head);
    keep.swap(h);
  }
  return p->value; // here
}
